def allocate_cents(total, weights):
    if isinstance(total, bool) or not isinstance(total, int):
        raise TypeError('total must be an integer, excluding bool')
    if not isinstance(weights, list):
        raise TypeError('weights must be a list')
    for weight in weights:
        if isinstance(weight, bool) or not isinstance(weight, int):
            raise TypeError('weights must contain integers, excluding bool')
    if total < 0:
        raise ValueError('total must be nonnegative')
    if not weights:
        raise ValueError('weights must be nonempty')
    if any(weight <= 0 for weight in weights):
        raise ValueError('weights must be positive')

    denominator = sum(weights)
    allocations = []
    remainders = []
    for weight in weights:
        allocation, remainder = divmod(total * weight, denominator)
        allocations.append(allocation)
        remainders.append(remainder)

    remaining = total - sum(allocations)
    order = sorted(range(len(weights)), key=lambda index: (-remainders[index], index))
    for index in order[:remaining]:
        allocations[index] += 1
    return allocations

import math


def categorical_loss_grad(logits, labels):
    if not isinstance(logits, list) or not logits:
        raise ValueError('logits must be a nonempty list')
    if not isinstance(labels, list) or len(labels) != len(logits):
        raise ValueError('labels must match the batch')
    if not isinstance(logits[0], list) or len(logits[0]) < 2:
        raise ValueError('at least two classes are required')
    classes = len(logits[0])
    rows = []
    for row in logits:
        if not isinstance(row, list) or len(row) != classes:
            raise ValueError('logits must be rectangular')
        values = []
        for value in row:
            if not isinstance(value, (int, float)):
                raise ValueError('logits must be finite numbers')
            try:
                value = float(value)
            except (TypeError, ValueError, OverflowError):
                raise ValueError('logits must be finite numbers') from None
            if not math.isfinite(value):
                raise ValueError('logits must be finite numbers')
            values.append(value)
        rows.append(values)
    for label in labels:
        if isinstance(label, bool) or not isinstance(label, int):
            raise ValueError('labels must be integer indices')
        if not 0 <= label < classes:
            raise ValueError('label out of range')
    batch = len(rows)
    terms = []
    gradient = []
    for row, label in zip(rows, labels):
        maximum = max(row)
        weights = [math.exp(value - maximum) for value in row]
        total = math.fsum(weights)
        # fsum preserves cancellation of large common offsets.
        terms.extend([maximum / batch, -row[label] / batch,
                      math.log(total) / batch])
        gradient.append([
            (weight / total - (1.0 if j == label else 0.0)) / batch
            for j, weight in enumerate(weights)
        ])
    try:
        loss = math.fsum(terms)
    except OverflowError:
        loss = float('inf')
    return loss, gradient

def check_contract(fn):
    def expect_error(value, expected):
        try:
            fn(value)
        except expected:
            return
        except Exception as exc:
            raise AssertionError(
                'wrong exception for {!r}: expected {}, got {}'.format(
                    value, expected.__name__, type(exc).__name__
                )
            ) from exc
        raise AssertionError(
            'expected {} for {!r}'.format(expected.__name__, value)
        )

    for value in (1, 2, 80, 443, 1024, 32768, 65534, 65535):
        result = fn(value)
        assert isinstance(result, int) and not isinstance(result, bool), (
            'result must remain an integer for {!r}'.format(value)
        )
        assert result == value, 'valid port changed: {!r}'.format(value)

    for value in (True, False, None, '80', '', 80.0, 1.5,
                  b'80', [], {}, (), set(), 1 + 0j):
        expect_error(value, TypeError)

    for value in (-10**100, -65535, -1, 0, 65536, 65537, 10**100):
        expect_error(value, ValueError)
